// Package appleroots holds the Apple root certificate that App Store signed transactions and
// notifications chain to (lite/src/lib/apple-roots.ts).
package appleroots

import "encoding/base64"

// AppleRootCAG3B64 is Apple Root CA - G3, DER, base64.
// Source: https://www.apple.com/certificateauthority/AppleRootCA-G3.cer
// SHA-256 fingerprint, as published by Apple:
//
//	63:34:3A:BF:B8:9A:6A:03:EB:B5:7E:9B:3F:5F:A7:BE:7C:4F:5C:75:6F:30:17:B3:A8:C4:88:C3:65:3E:91:79
//
// Valid 2014-04-30 to 2039-04-30.
const AppleRootCAG3B64 = ""

// AppleRootCAG3SHA256 is its SHA-256 fingerprint.
const AppleRootCAG3SHA256 = "63343abfb89a6a03ebb57e9b3f5fa7be7c4f5c756f3017b3a8c488c3653e9179"

// Production returns the roots trusted outside conformance mode.
func Production() [][]byte {
	der, err := base64.StdEncoding.DecodeString(AppleRootCAG3B64)
	if err != nil {
		panic(err)
	}
	return [][]byte{der}
}
